using System;using System.IO;using System.Runtime.InteropServices;using System.Reflection;using System.Web.Script.Serialization;using PptEase.Shader;
class RestyleGraffiti {
[STAThread]static int Main(string[] args){dynamic app=null,p=null;try{try{app=Marshal.GetActiveObject("PowerPoint.Application");}catch{app=Activator.CreateInstance(Type.GetTypeFromProgID("PowerPoint.Application"));}p=app.Presentations.Open(Path.GetFullPath(args[0]),-1,0,0);dynamic s=p.Slides.Item(2);var style=Assembly.LoadFrom(Path.GetFullPath(args[2])).GetType("PptEase.Host.Connect").GetMethod("StyleShaderControl",BindingFlags.Static|BindingFlags.NonPublic);
foreach(int gid in new[]{40,41}){dynamic group=null;for(int i=1;i<=s.Shapes.Count;i++)if((int)s.Shapes.Item(i).Id==gid)group=s.Shapes.Item(i);if(group==null)throw new Exception("Missing group");dynamic track=group.GroupItems.Item(1),knob=group.GroupItems.Item(2);float x=knob.Left,y=knob.Top;style.Invoke(null,new object[]{track,knob,true,gid==40,false,1});knob.Left=Math.Max((float)track.Left+4,Math.Min(x,(float)track.Left+(float)track.Width-(float)knob.Width-4));knob.Top=Math.Max((float)track.Top+4,Math.Min(y,(float)track.Top+(float)track.Height-(float)knob.Height-4));string pair=Guid.NewGuid().ToString("N");foreach(dynamic shape in new object[]{track,knob}){shape.Tags.Add("PPTEASE_CONTROL_PAIR",pair);shape.Tags.Add("PPTEASE_CONTROL_KIND",gid==40?"disk":"pad");}group.Tags.Add("PPTEASE_CONTROL_GROUP","1");group.LockAspectRatio=-1;}
var json=new JavaScriptSerializer{MaxJsonLength=ShaderPayload.MaximumBytes};for(int i=1;i<=s.Shapes.Count;i++){dynamic sh=s.Shapes.Item(i);if(String.IsNullOrEmpty((string)sh.Tags.Item(ShaderPayload.ManifestKey)))continue;var c=json.Deserialize<ShaderComponent>(ShaderPayload.Read(k=>(string)sh.Tags.Item(k)));foreach(var b in c.Bindings){b.StylePreset=1;b.ShowValue=false;}ShaderPayload.Write(json.Serialize(c),k=>(string)sh.Tags.Item(k),(k,v)=>sh.Tags.Add(k,v),k=>sh.Tags.Delete(k));}
p.SaveAs(Path.GetFullPath(args[1]),24,0);s.Export(Path.GetFullPath(args[3]),"PNG",1440,960);Console.WriteLine("Styled both grouped controls; preserved bindings and handle positions.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(p!=null)p.Close();}}
}
